            status.textContent=`${result.pages.length} ${result.pages.length===1?"page":"pages"} · Click a page to enlarge`;
            body.title="Click to enlarge. In the enlarged view, scroll to zoom and drag to move. PDF pages are images; text is not selectable.";
            result.pages.forEach((page,index)=>{const img=document.createElement("img");img.src=page;img.alt=`PDF page ${index+1}`;img.loading="lazy";img.tabIndex=0;img.setAttribute("role","button");img.setAttribute("aria-label",`Enlarge PDF page ${index+1}`);const enlarge=()=>{closePage?.();closePage=openPdfPage(overlay,img);};img.onclick=enlarge;img.onkeydown=event=>{if(event.key==="Enter" || event.key===" "){event.preventDefault();enlarge();}};body.append(img);});
