    public refreshOtherAnswers(load: (question: string) => Promise<QnaResponse>, source?: Element): void {
        const revision = ++this.crossFilterRevision;
        this.crossFilterObserver?.disconnect();
        let queue = Promise.resolve();
        const observer = new IntersectionObserver(entries => {
            for (const entry of entries) if (entry.isIntersecting) {
                const answer = entry.target as HTMLElement; observer.unobserve(answer);
                queue = queue.then(async () => {
                    if (revision !== this.crossFilterRevision || !answer.isConnected) return;
                    try {
                        const response = await load(answer.dataset.question || '');
                        if (revision !== this.crossFilterRevision || !answer.isConnected) return;
                        const scroll = this.messages.scrollTop;
                        this.render(response, answer.dataset.question || '');
                        const replacement = this.messages.lastElementChild!;
                        answer.replaceWith(replacement); this.messages.scrollTop = scroll;
                    } catch (error) {
                        if (revision !== this.crossFilterRevision || !answer.isConnected) return;
                        answer.replaceChildren();
                        const message = document.createElement('p'); message.textContent = `Could not refresh this answer: ${(error as Error).message}`;
                        const retry = document.createElement('button'); retry.textContent = 'Retry'; retry.onclick = () => observer.observe(answer);
                        answer.append(message, retry);
                    } finally { if (revision === this.crossFilterRevision) answer.removeAttribute('aria-busy'); }
                });
            }
        }, { root: this.messages, rootMargin: '150px' });
        this.crossFilterObserver = observer;
        this.messages.querySelectorAll<HTMLElement>('.askbics-qna__answer').forEach(answer => {
            if (answer === source) return;
            answer.setAttribute('aria-busy', 'true'); observer.observe(answer);
        });
    }
