    private paintChartLabels(scope: ParentNode = this.root): void {
        scope.querySelectorAll("svg").forEach(svg => {
            if (svg.tagName.toLowerCase() !== "svg") return;
            const keys = new Set(Array.from(svg.querySelectorAll("[data-highlight-key].is-selected")).map(mark => mark.getAttribute("data-highlight-key")));
            svg.classList.toggle("has-label-selection", keys.size > 0);
            svg.querySelectorAll("[data-label-key]").forEach(label => label.classList.toggle("is-selected-label", keys.has(label.getAttribute("data-label-key"))));
        });
    }
    private paintModelSelection(): void {
        this.root.querySelectorAll('[data-model-selection]').forEach(element => {
            const active = this.modelSelected.has(this.elementSelectionKeys.get(element) || '');
            element.classList.toggle(element.tagName === 'TD' ? 'is-selected-cell' : 'is-selected', active);
            element.setAttribute('aria-selected', String(active));
        });
        this.paintChartLabels();
    }
    private bindModelSelection(element: Element, rows: ModelSelection[], cell = false): void {
        if (!rows.length || rows.some(row => !row.length)) return;
        let key = this.modelSelectionKeys.get(rows);
        if (!key) { key = JSON.stringify(rows.map(row => [...row].sort((a,b) => JSON.stringify(a).localeCompare(JSON.stringify(b)))).sort((a,b) => JSON.stringify(a).localeCompare(JSON.stringify(b))));
            this.modelSelectionKeys.set(rows, key);
        }
        this.elementSelectionKeys.set(element, key);
        element.setAttribute('data-model-selection', String(++this.modelSelectionSequence)); element.setAttribute('tabindex', '0');
        const select = (event: MouseEvent | KeyboardEvent) => {
            event.stopPropagation(); event.preventDefault();
            const source = this.hostMode === 'teams' ? element.closest('.askbics-qna__answer') : undefined;
            if (this.crossFilterEnabled && !source) return;
            if (this.crossFilterEnabled && source !== this.selectionSource) this.modelSelected.clear();
            this.selectionSource = source || undefined;
            const selected = this.modelSelected.has(key);
            const additive = event.ctrlKey || event.metaKey;
            const remove = selected && (additive || this.modelSelected.size === 1);
            if (!additive) this.modelSelected.clear();
            if (remove) this.modelSelected.delete(key); else this.modelSelected.set(key, rows);
            this.paintModelSelection();
            this.dispatchModelSelection();
        };
        element.addEventListener('click', event => select(event as MouseEvent));
        element.addEventListener('keydown', event => { const key = (event as KeyboardEvent).key; if (key === 'Enter' || key === ' ') select(event as KeyboardEvent); });
        element.classList.toggle(cell ? 'is-selected-cell' : 'is-selected', this.modelSelected.has(key));
    }
