    private modelValueSuggestions(query: string, text: string, limit = 12): Array<{label: string; detail: string}> {
        const before = text.slice(0, text.lastIndexOf("@")).toLowerCase();
        const fields = this.availableConfiguration().fields.flatMap(field => [field, field.replace(/\s+Name$/i, "")].map(alias => ({ field, position: before.lastIndexOf(alias.toLowerCase()), length: alias.length })))
            .filter(item => item.position >= 0 && (item.position === 0 || !/[a-z0-9]/i.test(before[item.position - 1])))
            .sort((a,b) => b.position - a.position || b.length - a.length);
        const scoped = fields[0]?.field;
        const q = query.trim().toLowerCase();
        const allowed = new Set(this.suggestionConfiguration().fields);
        return (this.valueOptions?.() || []).filter(item => allowed.has(item.detail) && (!scoped || item.detail === scoped) && item.label.toLowerCase().includes(q))
            .sort((a,b) => Number(b.label.toLowerCase().startsWith(q)) - Number(a.label.toLowerCase().startsWith(q))).slice(0, limit);
    }
