    private inputTerms(text: string): Array<{ start: number; end: number; kind: "field" | "measure" | "value" }> {
        const terms = this.engine.recognizedTerms(text);
        if (!this.automaticGroupingEnabled?.()) return terms;
        const candidates = [...terms];
        const labels = [...(this.measureOptions?.() || []).map(label => ({label, kind: "measure" as const})), ...(this.groupingOptions?.() || []).map(label => ({ label, kind: "field" as const })), ...this.modelSynonymOptions().map(item => ({label: item.label, kind: item.detail === "Measure" ? "measure" as const : "field" as const})),
            ...(this.valueOptions?.() || []).map(item => ({ label: item.label, kind: "value" as const }))];
        // Month-year syntax is recognized by the query planner independently
        // of the field currently returned by Power BI.
        candidates.push(...recognizedTimeTerms(text, this.timeSettings?.(), labels.map(item => item.label), true));
        for (const { label, kind } of labels) {
            const escaped = label.replace(/[.*+?^${}()|[\]\\]/g, "\\$&").replace(/\s+/g, "\\s+");
            const pattern = new RegExp(`\\b${escaped}\\b`, "gi");
            let match: RegExpExecArray | null;
            while ((match = pattern.exec(text))) candidates.push({ start: match.index, end: match.index + match[0].length, kind });
        }
        const chosen: typeof candidates = [];
        candidates.sort((a, b) => (b.end - b.start) - (a.end - a.start)).forEach(term => {
            if (!chosen.some(other => term.start < other.end && term.end > other.start)) chosen.push(term);
        });
        return chosen.sort((a, b) => a.start - b.start);
    }
