                loading.setAttribute("aria-live", "polite");
                const sparkle = document.createElement("span"); sparkle.className = "askbics-qna__thinking-sparkle"; sparkle.textContent = "✦"; sparkle.setAttribute("aria-hidden", "true");
                const copy = document.createElement("span"); copy.className = "askbics-qna__thinking-copy";
                const title = document.createElement("strong"); title.textContent = "Working on your question…";
                const dots = document.createElement("span"); dots.className = "askbics-qna__thinking-dots"; dots.setAttribute("aria-hidden", "true");
                for (let i = 0; i < 3; i++) dots.append(document.createElement("i"));
                const stage = document.createElement("small"); stage.textContent = "Preparing the data request…";
