        if (!questionShown && !replaceAnswer && this.engine.getLayoutSettings().conversationMode === "latest" && this.hasConversation) { this.messages.replaceChildren(); this.questions = []; }
        if (!this.hasConversation) { this.messages.replaceChildren(); this.hasConversation = true; }
        if (!persist && !replaceAnswer) this.input.value = ""; this.renderInputHighlight(); this.closeSuggestions(); if (!replaceAnswer && !questionShown) this.addBubble(this.displayQuestion(text), "user", this.messages, text); else if (replaceAnswer) this.messages.querySelector(".askbics-qna__answer:last-child")?.remove();
