    private numericValue(value: string): number | null { const normalized = String(value || "").replace(/[^0-9.+-]/g, ""); if (!normalized || normalized === "." || normalized === "-") return null; const number = Number(normalized); return Number.isFinite(number) ? number : null; }
    private evaluateFormula(formula: string, values: Map<string, number | null>): number | null {
        return calculateFormula(formula, values);
    }
    private compareTableValues(column: string, a: string, b: string): number { if (/\bmonth\b/i.test(column)) { const months = ["january", "february", "march", "april", "may", "june", "july", "august", "september", "october", "november", "december"]; const rank = (value: string) => { const normalized = value.trim().toLowerCase(); const named = months.findIndex((month) => month === normalized || month.startsWith(normalized.slice(0, 3))); if (named >= 0) return named; const numeric = normalized.match(/(?:^|\D)(1[0-2]|0?[1-9])(?:\D|$)/); return numeric ? Number(numeric[1]) - 1 : 99; }; const result = rank(a) - rank(b); if (result) return result; } if (/\bquarter\b/i.test(column)) { const result = Number(a.match(/[1-4]/)?.[0] || 99) - Number(b.match(/[1-4]/)?.[0] || 99); if (result) return result; } return a.localeCompare(b, undefined, { numeric: true, sensitivity: "base" }); }

