    private arcPath(cx: number, cy: number, outer: number, inner: number, start: number, end: number): string { const polar = (radius: number, angle: number) => [cx + Math.cos(angle) * radius, cy + Math.sin(angle) * radius]; const startOuter = polar(outer, start); const endOuter = polar(outer, end); const large = end - start > Math.PI ? 1 : 0; if (end - start >= Math.PI * 1.999) return inner ? `M ${cx} ${cy - outer} A ${outer} ${outer} 0 1 1 ${cx - .01} ${cy - outer} M ${cx} ${cy - inner} A ${inner} ${inner} 0 1 0 ${cx - .01} ${cy - inner}` : `M ${cx} ${cy - outer} A ${outer} ${outer} 0 1 1 ${cx - .01} ${cy - outer} Z`; if (!inner) return `M ${cx} ${cy} L ${startOuter[0]} ${startOuter[1]} A ${outer} ${outer} 0 ${large} 1 ${endOuter[0]} ${endOuter[1]} Z`; const endInner = polar(inner, end); const startInner = polar(inner, start); return `M ${startOuter[0]} ${startOuter[1]} A ${outer} ${outer} 0 ${large} 1 ${endOuter[0]} ${endOuter[1]} L ${endInner[0]} ${endInner[1]} A ${inner} ${inner} 0 ${large} 0 ${startInner[0]} ${startInner[1]} Z`; }

