    private displayQuestion(question: string): string { question = question.replace(/;\s*answerFilters:\s*\S+\s*$/i, ""); const match = question.match(/^\s*(table|matrix)\s*;\s*rows\s*:\s*([^;]*)\s*;\s*columns\s*:\s*([^;]*)\s*;\s*values\s*:\s*(.*)\s*$/i); if (!match) return question; const mode = match[1].toLowerCase(); const rows = match[2].split(/\s*>\s*|\s*,\s*/).map((item) => item.trim()).filter(Boolean); const columns = match[3].split(/\s*>\s*|\s*,\s*/).map((item) => item.trim()).filter(Boolean); const measures = match[4].split(/\s*,\s*/).map((item) => item.trim()).filter(Boolean); const measureText = measures.join(" and ") || "values"; const rowText = rows.length ? ` by ${rows.join(" and ")}` : ""; const columnText = mode === "matrix" && columns.length ? `, with columns by ${columns.join(" and ")}` : ""; return `Show ${measureText}${rowText}${columnText} as a ${mode}.`; }

    private editableQuestion(question: string): string {
        const readable = this.displayQuestion(question).replace(/\.$/, "");
        const filters = this.engine.answerFilters(question).map((filter) => `${filter.field} (${filter.values.join(" | ")})`);
        return filters.length ? `${readable}, ${filters.join(", ")}` : readable;
    }

    private addBubble(text: string, role: "user" | "assistant", parent: HTMLElement = this.messages, editValue = text): void { const bubble = document.createElement("div"); bubble.className = `askbics-qna__bubble askbics-qna__bubble--${role}`; const content = document.createElement("span"); content.className = "askbics-qna__bubble-text"; content.textContent = text; content.addEventListener("mousedown", (event) => event.stopPropagation()); bubble.appendChild(content); if (role === "user") { const edit = document.createElement("button"); edit.type = "button"; edit.className = "askbics-qna__edit"; edit.textContent = "✎"; edit.setAttribute("aria-label", "Edit this question"); edit.dataset.tooltip = "Edit question"; edit.addEventListener("click", () => { this.clearQuestionSelection(); const editable = this.editableQuestion(editValue); this.input.value = editable; this.renderInputHighlight(); this.showAutocomplete(); this.input.focus(); this.input.setSelectionRange(editable.length, editable.length); }); bubble.appendChild(edit); } parent.appendChild(bubble); }
    private addPromptChips(labels: string[], parent: HTMLElement = this.messages): void { const row = document.createElement("div"); row.className = "askbics-qna__chips"; labels.slice(0, 6).forEach((label) => { const button = document.createElement("button"); button.type = "button"; button.textContent = label; button.addEventListener("click", () => this.submit(label)); row.appendChild(button); }); parent.appendChild(row); }
    private saveReport(question: string, response: QnaResponse, button: HTMLButtonElement): void {
        if (this.savedReports.some((item) => item.question.toLowerCase() === question.toLowerCase())) return;
        const overlay = document.createElement("div"); overlay.className = "askbics-qna__config-overlay"; const panel = document.createElement("section"); panel.className = "askbics-qna__config-panel askbics-qna__save-section-panel"; panel.setAttribute("role", "dialog"); panel.setAttribute("aria-modal", "true"); const head = document.createElement("div"); head.className = "askbics-qna__config-head"; const heading = document.createElement("div"); const title = document.createElement("h3"); title.textContent = "Save report"; const subtitle = document.createElement("p"); subtitle.textContent = "Choose the section where this report should appear."; heading.append(title, subtitle); const close = document.createElement("button"); close.type = "button"; this.setCloseIcon(close); close.setAttribute("aria-label", "Close save report dialog"); head.append(heading, close); const sections = document.createElement("div"); sections.className = "askbics-qna__section-choices"; let selectedId = this.defaultReportSectionId; this.reportSections.forEach((section) => { const label = document.createElement("label"); const input = document.createElement("input"); input.type = "radio"; input.name = "askbics-save-section"; input.value = section.id; input.checked = section.id === selectedId; input.addEventListener("change", () => { if (input.checked) selectedId = section.id; }); const name = document.createElement("span"); name.textContent = section.name; const status = document.createElement("small"); status.textContent = section.passwordHash ? (this.sectionIsUnlocked(section) ? "Unlocked" : "Protected") : "Open"; label.append(input, name, status); sections.appendChild(label); }); const actions = document.createElement("div"); actions.className = "askbics-qna__config-actions"; const cancel = document.createElement("button"); cancel.type = "button"; cancel.textContent = "Cancel"; const save = document.createElement("button"); save.type = "button"; save.className = "is-primary"; save.textContent = "Save report"; actions.append(cancel, save); panel.append(head, sections, actions); overlay.appendChild(panel); this.root.appendChild(overlay); const dismiss = () => overlay.remove(); close.addEventListener("click", dismiss); cancel.addEventListener("click", dismiss); overlay.addEventListener("pointerdown", (event) => { if (event.target === overlay) dismiss(); }); save.addEventListener("click", () => { const section = this.reportSections.find((item) => item.id === selectedId) || this.reportSections[0]; this.ensureSectionAccess(section, () => { const name = response.chart?.title || response.kpi?.title || response.table?.columns.join(" by ") || question; const random = new Uint32Array(2); crypto.getRandomValues(random); this.savedReports.push({ id: `${Date.now()}-${random[0].toString(36)}${random[1].toString(36)}`, name, question, modelQuery: response.modelQuery, sectionId: section.id, createdAt: Date.now(), size: response.kpi ? "small" : response.chart ? "large" : "medium" }); this.savedReports = this.savedReports.slice(-20); dismiss(); button.classList.add("is-saved"); button.replaceChildren(); const icon = document.createElement("span"); icon.textContent = "✓"; button.append(icon, document.createTextNode(" Saved")); button.disabled = true; this.updateSavedCount(); this.onStateChanged?.(); }); }); close.focus();
    }
    private async passwordDigest(password: string, salt: string): Promise<string> { const encoder = new TextEncoder(); const key = await crypto.subtle.importKey("raw", encoder.encode(password), "PBKDF2", false, ["deriveBits"]); const bits = await crypto.subtle.deriveBits({ name: "PBKDF2", hash: "SHA-256", salt: encoder.encode(salt), iterations: 150000 }, key, 256); return Array.from(new Uint8Array(bits)).map((value) => value.toString(16).padStart(2, "0")).join(""); }
    private sectionUnlockKey(section: SavedReportSection): string { return `askbics-section-unlock:${section.id}:${(section.passwordHash || "open").slice(0, 16)}`; }
