        if (!this.automaticGroupingEnabled?.() && this.savedReports.some(report => report.modelQuery)) { this.showModelReports(); return; }
        this.showingSavedDashboard = true; this.expandedReportId = ""; this.root.classList.add("is-saved-dashboard"); this.closeSuggestions(); this.messages.replaceChildren(); this.messages.scrollTop = 0;
        const activeRange = this.dashboardRange(); this.engine.setDashboardDateRange(activeRange?.start, activeRange?.end); const dashboardSelection = this.engine.selectionSummary(); let activeSection = this.reportSections.find((section) => section.id === this.activeReportSectionId) || this.reportSections[0]; if (!this.sectionIsUnlocked(activeSection)) { activeSection = this.reportSections.find((section) => !section.passwordHash) || this.reportSections[0]; this.activeReportSectionId = activeSection.id; } const sectionReports = this.savedReports.filter((report) => (report.sectionId || "general") === activeSection.id);
        const view = document.createElement("section"); view.className = `askbics-qna__saved-view askbics-qna__dashboard askbics-qna__dashboard-v2${this.dashboardEditMode ? " is-editing" : ""}`;
        const head = document.createElement("div"); head.className = "askbics-qna__saved-head askbics-qna__dashboard-head"; const back = document.createElement("button"); back.type = "button"; back.className = "askbics-qna__saved-back"; const backIcon = this.svg("svg"); backIcon.setAttribute("viewBox", "0 0 20 20"); backIcon.setAttribute("aria-hidden", "true"); const backPath = this.svg("path"); backPath.setAttribute("d", "M9 5 4 10l5 5M4.5 10H16"); backIcon.appendChild(backPath); const backText = document.createElement("span"); backText.textContent = "Back to Q&A"; back.append(backIcon, backText); back.setAttribute("aria-label", "Return to the askBICS conversation"); back.addEventListener("click", () => this.rebuildConversation()); const title = document.createElement("div"); const strong = document.createElement("h2"); strong.textContent = activeSection.name; const meta = document.createElement("p"); meta.textContent = `${sectionReports.length} live ${sectionReports.length === 1 ? "report" : "reports"} · ${activeRange?.label || "All dates"} · Updated ${new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })}`; title.append(strong, meta); const actions = document.createElement("div"); actions.className = "askbics-qna__dashboard-head-actions";
